function doPost(e) {
  try {
    // לקבל את ה-JSON ששלח האתר
    const data = JSON.parse(e.postData.contents);

    // הגיליון הפעיל (אותו אחד שאנחנו עורכים בו)
    const sheet = SpreadsheetApp.getActiveSheet();

    // הוספת שורה חדשה: תאריך, שם, אימייל, הודעה
    sheet.appendRow([
      new Date(),
      data.name,
      data.email,
      data.message
    ]);

    // החזרת הצלחה לאתר
    return ContentService
      .createTextOutput(JSON.stringify({ ok: true }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    // אם משהו השתבש — מחזירים שגיאה
    return ContentService
      .createTextOutput(JSON.stringify({ ok: false, error: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

const APPS_SCRIPT_URL = 'https://script.google.com/macros/s/XXX/exec';

const form = document.querySelector('#contact-form');
const statusEl = document.querySelector('#form-status');

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  statusEl.textContent = 'שולח...';

  // אוספים את הנתונים מהטופס
  const data = {
    name: form.name.value,
    email: form.email.value,
    message: form.message.value
  };

  try {
    // שולחים ל-Apps Script
    const response = await fetch(APPS_SCRIPT_URL, {
      method: 'POST',
      body: JSON.stringify(data)
    });
    const result = await response.json();

    if (result.ok) {
      statusEl.textContent = 'תודה! נחזור אליך בקרוב.';
      form.reset();
    } else {
      statusEl.textContent = 'שגיאה. נסה/י שוב.';
    }
  } catch (err) {
    statusEl.textContent = 'שגיאת חיבור. בדק/י אינטרנט.';
  }
});
